(()=>{let promptEvent=null;const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;function paint(){const host=document.getElementById('pwa-install');if(!host)return;host.innerHTML='<p class="help-copy" role="status">'+(installed()?'Bạn đang dùng Kanban Zen Studio dưới dạng ứng dụng.':promptEvent?'Cài Kanban Zen Studio để mở nhanh từ màn hình chính.':/iPhone|iPad|iPod/.test(navigator.userAgent)?'Trên Safari: chọn Chia sẻ → Thêm vào Màn hình chính → Thêm.':'Mở menu trình duyệt và chọn Cài đặt ứng dụng hoặc Thêm vào màn hình chính nếu có. Trình duyệt sẽ tự quyết định khi nào cho phép cài đặt.')+'</p>'+(!installed()&&promptEvent?'<button type="button" class="btn primary" id="pwa-install-button">Cài đặt Kanban Zen Studio</button>':'');const button=document.getElementById('pwa-install-button');if(button)button.onclick=async()=>{const event=promptEvent;if(!event)return;promptEvent=null;button.disabled=true;try{await event.prompt();await event.userChoice;}catch{ }finally{paint();}};}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;paint();});window.addEventListener('appinstalled',()=>{promptEvent=null;paint();});matchMedia('(display-mode: standalone)').addEventListener('change',paint);
new MutationObserver(()=>{const body=document.getElementById('editor-body');if(body&&document.getElementById('save-profile')&&!document.getElementById('pwa-install')){const group=document.createElement('details');group.className='wf-settings-group wf-settings-app';const summary=document.createElement('summary');summary.textContent='Cài đặt ứng dụng';const content=document.createElement('div');content.className='wf-settings-content';const section=document.createElement('section');section.id='pwa-install';section.className='profile-card';content.append(section);group.append(summary,content);const session=[...body.querySelectorAll('.wf-settings-group')].find(item=>item.querySelector('.settings-signout'));if(session)body.insertBefore(group,session);else body.append(group);paint();}}).observe(document.getElementById('editor-body'),{childList:true,subtree:true});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
})();